parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "approved": {
      "type": "boolean",
      "description": "False if there is any factual accuracy or citation integrity issue."
    },
    "issues": {
      "type": "array",
      "description": "Specific, actionable problems found. Empty if none.",
      "items": {
        "type": "object",
        "properties": {
          "type": {
            "type": "string",
            "description": "One of: factual_accuracy, citation_integrity, brief_coverage, structural, tone."
          },
          "detail": {
            "type": "string",
            "description": "Specific explanation of the problem, referencing the exact draft text and, where relevant, which finding it conflicts with."
          },
          "quoted_text": {
            "type": "string",
            "description": "The exact text from the draft this issue refers to. Use an empty string if the problem is something missing."
          }
        },
        "required": ["type", "detail"]
      }
    },
    "revision_notes": {
      "type": "string",
      "description": "Direct, actionable instructions for the drafting agent covering only the issues found. Empty string if approved."
    }
  },
  "required": ["approved", "issues", "revision_notes"]
}

parameters.jsCode:
const item = $input.first().json;
const out = item.output;
const trigger = $('When Executed by Another Workflow').first().json;
const draft = trigger.draft;
const sourcesUsed = trigger.sources_used || [];
const today = $now.toFormat('yyyy-MM-dd');
const thisYear = Number($now.toFormat('yyyy'));

// 1. Drop date or recency complaints that code can disprove
const datePhrases = /future|today['’]?s date|time relevance|timeliness|recency|publication date|dated in|dated on|date of publication/i;
let droppedDateIssues = 0;
const issues = [];
for (const issue of (out.issues || [])) {
  const text = `${issue.detail ?? ''} ${issue.quoted_text ?? ''}`;
  const years = (text.match(/\b20\d{2}\b/g) || []).map(Number);
  const isoDates = text.match(/\b\d{4}-\d{2}-\d{2}\b/g) || [];
  const hasFutureDate = isoDates.some(d => d > today) || years.some(y => y > thisYear);
  if (datePhrases.test(text) && years.length > 0 && !hasFutureDate) {
    droppedDateIssues++;
    continue;
  }
  issues.push(issue);
}

let approved = out.approved;
let revisionNotes = out.revision_notes || '';
if (droppedDateIssues > 0) {
  if (issues.length === 0) approved = true;
  revisionNotes = issues.map(i => i.detail).join(' ');
}

// 2. Structural check: every cited URL must appear in the draft text
const missingFromDraft = sourcesUsed.filter(url => !draft.includes(url));
if (missingFromDraft.length > 0) {
  approved = false;
  issues.push({
    type: 'structural',
    detail: `The draft is missing a References/Sources section, or it does not list the following cited URL(s) verbatim: ${missingFromDraft.join(', ')}.`,
    quoted_text: ''
  });
  revisionNotes = [revisionNotes, `Add a References section listing: ${missingFromDraft.join(', ')}.`].filter(Boolean).join(' ');
}
if (approved) revisionNotes = '';

return [{
  json: {
    topic: trigger.topic,
    approved,
    issues,
    revision_notes: revisionNotes,
    dropped_date_issues: droppedDateIssues
  }
}];
